// Package glob implements a small glob pattern matcher.
//
// Supported syntax:
//
//	*          any sequence of characters (including none)
//	**         same as * (no separators are configured)
//	?          exactly one character
//	[abc]      one character from the list
//	[!abc]     one character not in the list
//	[a-z]      one character in the range
//	[!a-z]     one character outside the range
//	{a,b,c}    alternatives (may be nested)
//	\x         the literal character x
//
// A pattern matches a string only if it matches the whole string.
package glob

import (
	"errors"
	"fmt"
	"strings"
	"unicode/utf8"
)

// Glob is a compiled pattern.
type Glob struct {
	root *node
}

// Compile parses pattern and returns a matcher for it.
func Compile(pattern string) (*Glob, error) {
	lx := newLexer(pattern)
	root, err := parse(lx)
	if err != nil {
		return nil, err
	}
	return &Glob{root: root}, nil
}

// MustCompile is like Compile but panics on error.
func MustCompile(pattern string) *Glob {
	g, err := Compile(pattern)
	if err != nil {
		panic(err)
	}
	return g
}

// Match reports whether s matches the pattern.
func (g *Glob) Match(s string) bool {
	if g == nil || g.root == nil {
		return false
	}
	return matchSeq(g.root.children, s)
}

// ---------------------------------------------------------------------------
// Lexer

type tokenKind int

const (
	tkEOF tokenKind = iota
	tkError
	tkText
	tkAny
	tkSuper
	tkSingle
	tkNot
	tkRangeOpen
	tkRangeClose
	tkRangeLo
	tkRangeHi
	tkRangeBetween
	tkTermsOpen
	tkTermsClose
	tkSeparator
)

type token struct {
	kind tokenKind
	raw  string
}

const (
	chAny        = '*'
	chSingle     = '?'
	chEscape     = '\\'
	chRangeOpen  = '['
	chRangeClose = ']'
	chTermsOpen  = '{'
	chTermsClose = '}'
	chComma      = ','
	chNot        = '!'
	chBetween    = '-'
)

var (
	textBreakers  = []rune{chAny, chSingle, chRangeOpen, chTermsOpen}
	termsBreakers = []rune{chAny, chSingle, chRangeOpen, chTermsOpen, chTermsClose, chComma}
)

const eof rune = -1

type lexer struct {
	data       string
	pos        int
	lastWidth  int
	termsLevel int
	queue      []token
	done       bool
}

func newLexer(s string) *lexer {
	return &lexer{data: s}
}

func (l *lexer) read() rune {
	if l.pos >= len(l.data) {
		l.lastWidth = 0
		return eof
	}
	r, w := utf8.DecodeRuneInString(l.data[l.pos:])
	l.pos += w
	l.lastWidth = w
	return r
}

func (l *lexer) unread() {
	l.pos -= l.lastWidth
	l.lastWidth = 0
}

func (l *lexer) peek() (rune, int) {
	if l.pos >= len(l.data) {
		return eof, 0
	}
	return utf8.DecodeRuneInString(l.data[l.pos:])
}

func (l *lexer) push(k tokenKind, raw string) {
	l.queue = append(l.queue, token{kind: k, raw: raw})
}

func (l *lexer) fail(msg string) {
	l.push(tkError, msg)
	l.done = true
}

// next returns the next token in the stream.
func (l *lexer) next() token {
	for len(l.queue) == 0 {
		if l.done {
			return token{kind: tkEOF}
		}
		l.fetchItem()
	}
	t := l.queue[0]
	l.queue = l.queue[1:]
	return t
}

func (l *lexer) inTerms() bool { return l.termsLevel > 0 }

func (l *lexer) fetchItem() {
	r := l.read()
	switch {
	case r == eof:
		l.push(tkEOF, "")
		l.done = true
	case r == chTermsOpen:
		l.termsLevel++
		l.push(tkTermsOpen, string(r))
	case r == chComma && l.inTerms():
		l.push(tkSeparator, string(r))
	case r == chTermsClose && l.inTerms():
		l.push(tkTermsClose, string(r))
		l.termsLevel--
	case r == chRangeOpen:
		l.push(tkRangeOpen, string(r))
		l.fetchRange()
	case r == chSingle:
		l.push(tkSingle, string(r))
	case r == chAny:
		if n, w := l.peek(); n == chAny {
			l.pos += w
			l.push(tkSuper, string(r)+string(n))
		} else {
			l.push(tkAny, string(r))
		}
	default:
		l.unread()
		if l.inTerms() {
			l.fetchText(termsBreakers)
		} else {
			l.fetchText(textBreakers)
		}
	}
}

func (l *lexer) fetchRange() {
	var (
		wantHi    bool
		wantClose bool
		seenNot   bool
	)
	for {
		r := l.read()
		if r == eof {
			l.fail("unexpected end of input")
			return
		}
		if wantClose {
			if r != chRangeClose {
				l.fail("expected close range character")
				return
			}
			l.push(tkRangeClose, string(r))
			return
		}
		if wantHi {
			l.push(tkRangeHi, string(r))
			wantClose = true
			continue
		}
		if !seenNot && r == chNot {
			l.push(tkNot, string(r))
			seenNot = true
			continue
		}
		if n, w := l.peek(); n == chBetween {
			l.pos += w
			l.push(tkRangeLo, string(r))
			l.push(tkRangeBetween, string(n))
			wantHi = true
			continue
		}
		l.unread()
		l.fetchText([]rune{chRangeClose})
		if l.read() == chRangeClose {
			l.push(tkRangeClose, string(chRangeClose))
			return
		}
	}
}

func (l *lexer) fetchText(breakers []rune) {
	var buf []rune
	escaped := false
	for {
		r := l.read()
		if r == eof {
			break
		}
		if !escaped {
			if r == chEscape {
				escaped = true
				continue
			}
			if containsRune(breakers, r) {
				l.unread()
				break
			}
		}
		escaped = false
		buf = append(buf, r)
	}
	if len(buf) > 0 {
		l.push(tkText, string(buf))
	}
}

func containsRune(rs []rune, r rune) bool {
	for _, x := range rs {
		if x == r {
			return true
		}
	}
	return false
}

// ---------------------------------------------------------------------------
// Parser / AST

type nodeKind int

const (
	kindPattern nodeKind = iota // concatenation of children
	kindAnyOf                   // alternatives (children are patterns)
	kindText
	kindAny
	kindSuper
	kindSingle
	kindRange
	kindList
)

type node struct {
	kind     nodeKind
	parent   *node
	children []*node

	text   string // kindText
	lo, hi rune   // kindRange
	not    bool   // kindRange, kindList
	chars  string // kindList
}

func newNode(k nodeKind) *node { return &node{kind: k} }

func (n *node) insert(child *node) {
	child.parent = n
	n.children = append(n.children, child)
}

func parse(lx *lexer) (*node, error) {
	root := newNode(kindPattern)
	cur := root
	for {
		t := lx.next()
		switch t.kind {
		case tkEOF:
			return root, nil
		case tkError:
			return nil, errors.New(t.raw)
		case tkText:
			n := newNode(kindText)
			n.text = t.raw
			cur.insert(n)
		case tkAny:
			cur.insert(newNode(kindAny))
		case tkSuper:
			cur.insert(newNode(kindSuper))
		case tkSingle:
			cur.insert(newNode(kindSingle))
		case tkRangeOpen:
			n, err := parseRange(lx)
			if err != nil {
				return nil, err
			}
			cur.insert(n)
		case tkTermsOpen:
			anyOf := newNode(kindAnyOf)
			cur.insert(anyOf)
			p := newNode(kindPattern)
			anyOf.insert(p)
			cur = p
		case tkSeparator:
			if cur.parent == nil {
				return nil, errors.New("unexpected separator")
			}
			p := newNode(kindPattern)
			cur.parent.insert(p)
			cur = p
		case tkTermsClose:
			if cur.parent == nil || cur.parent.parent == nil {
				return nil, errors.New("unexpected terms close")
			}
			cur = cur.parent.parent
		default:
			return nil, fmt.Errorf("unexpected token: %q", t.raw)
		}
	}
}

func parseRange(lx *lexer) (*node, error) {
	var (
		not   bool
		lo    rune
		hi    rune
		chars string
	)
	for {
		t := lx.next()
		switch t.kind {
		case tkEOF:
			return nil, errors.New("unexpected end")
		case tkError:
			return nil, errors.New(t.raw)
		case tkNot:
			not = true
		case tkRangeLo:
			r, w := utf8.DecodeRuneInString(t.raw)
			if len(t.raw) > w {
				return nil, errors.New("unexpected length of lo character")
			}
			lo = r
		case tkRangeBetween:
			// nothing to do
		case tkRangeHi:
			r, w := utf8.DecodeRuneInString(t.raw)
			if len(t.raw) > w {
				return nil, errors.New("unexpected length of lo character")
			}
			hi = r
			if hi < lo {
				return nil, fmt.Errorf("hi character '%s' should be greater than lo '%s'", string(hi), string(lo))
			}
		case tkText:
			chars = t.raw
		case tkRangeClose:
			isRange := lo != 0 && hi != 0
			isChars := chars != ""
			if isChars == isRange {
				return nil, errors.New("could not parse range")
			}
			if isRange {
				n := newNode(kindRange)
				n.lo, n.hi, n.not = lo, hi, not
				return n, nil
			}
			n := newNode(kindList)
			n.chars, n.not = chars, not
			return n, nil
		default:
			return nil, fmt.Errorf("unexpected token in range: %q", t.raw)
		}
	}
}

// ---------------------------------------------------------------------------
// Matching

// matchSeq reports whether s is fully matched by the concatenation of nodes.
func matchSeq(nodes []*node, s string) bool {
	if len(nodes) == 0 {
		return s == ""
	}
	n, rest := nodes[0], nodes[1:]
	switch n.kind {
	case kindPattern:
		// A nested pattern is simply spliced into the sequence.
		return matchSeq(append(append([]*node{}, n.children...), rest...), s)
	case kindText:
		if !strings.HasPrefix(s, n.text) {
			return false
		}
		return matchSeq(rest, s[len(n.text):])
	case kindAny, kindSuper:
		if len(rest) == 0 {
			return true
		}
		for i := 0; ; {
			if matchSeq(rest, s[i:]) {
				return true
			}
			if i >= len(s) {
				return false
			}
			_, w := utf8.DecodeRuneInString(s[i:])
			i += w
		}
	case kindSingle:
		if s == "" {
			return false
		}
		_, w := utf8.DecodeRuneInString(s)
		return matchSeq(rest, s[w:])
	case kindRange:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := r >= n.lo && r <= n.hi
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:])
	case kindList:
		if s == "" {
			return false
		}
		r, w := utf8.DecodeRuneInString(s)
		in := strings.ContainsRune(n.chars, r)
		if in == n.not {
			return false
		}
		return matchSeq(rest, s[w:])
	case kindAnyOf:
		for _, alt := range n.children {
			seq := append(append([]*node{}, alt.children...), rest...)
			if matchSeq(seq, s) {
				return true
			}
		}
		return false
	}
	return false
}
EOF
echo ok"}

