// Package config loads the linter configuration from a .wrapcheck
// configuration file located in the working directory or in the
// user's home directory.
package config

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// DefaultIgnoreSigs is the default set of signature substrings that are
// considered to already wrap (or create) an error.
var DefaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

// Config holds the user configurable options of the linter.
type Config struct {
	// IgnoreSigs is a list of substrings; a function whose signature
	// contains any of them is not reported. Overrides the defaults.
	IgnoreSigs []string

	// ExtraIgnoreSigs extends IgnoreSigs without replacing it.
	ExtraIgnoreSigs []string

	// IgnoreSigRegexps is a list of regular expressions matched against
	// the function signature.
	IgnoreSigRegexps []string

	// IgnorePackageGlobs is a list of glob patterns matched against the
	// import path of the package defining the called function.
	IgnorePackageGlobs []string

	// IgnoreInterfaceRegexps is a list of regular expressions matched
	// against the name of the interface a method is called on.
	IgnoreInterfaceRegexps []string

	// ReportInternalErrors enables reporting of unwrapped errors that
	// originate from the package under analysis.
	ReportInternalErrors bool
}

// Default returns the default configuration.
func Default() Config {
	return Config{
		IgnoreSigs: append([]string(nil), DefaultIgnoreSigs...),
	}
}

// ParseError is returned when the configuration file exists but cannot be
// read or parsed.
type ParseError struct{ Err error }

func (e *ParseError) Error() string { return e.Err.Error() }
func (e *ParseError) Unwrap() error { return e.Err }

// DecodeError is returned when the configuration file was parsed but its
// values cannot be converted into a Config.
type DecodeError struct{ Err error }

func (e *DecodeError) Error() string { return e.Err.Error() }
func (e *DecodeError) Unwrap() error { return e.Err }

// Base name (without extension) of the configuration file.
const configName = ".wrapcheck"

// Extensions searched for, in order of priority.
var configExts = []string{
	"json", "toml", "yaml", "yml", "properties", "props", "prop",
	"hcl", "tfvars", "dotenv", "env", "ini",
}

// searchPaths returns the directories searched for a configuration file.
func searchPaths() []string {
	var paths []string
	if wd, err := filepath.Abs("."); err == nil {
		paths = append(paths, wd)
	}
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		if abs, err := filepath.Abs(home); err == nil {
			paths = append(paths, abs)
		}
	}
	return paths
}

func isRegularFile(path string) bool {
	st, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !st.IsDir()
}

// findFile locates the configuration file, returning "" if none exists.
func findFile() string {
	for _, dir := range searchPaths() {
		for _, ext := range configExts {
			p := filepath.Join(dir, configName+"."+ext)
			if isRegularFile(p) {
				return p
			}
		}
		p := filepath.Join(dir, configName)
		if isRegularFile(p) {
			return p
		}
	}
	return ""
}

// Load locates, reads and decodes the configuration file. When no file is
// present the default configuration is returned.
func Load() (Config, error) {
	cfg := Default()

	path := findFile()
	if path == "" {
		return cfg, nil
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return cfg, &ParseError{Err: err}
	}

	raw := map[string]interface{}{}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return cfg, &ParseError{Err: fmt.Errorf("While parsing config: %s", err.Error())}
	}
	settings := normalizeKeys(raw)

	if err := decodeInto(settings, &cfg); err != nil {
		return cfg, &DecodeError{Err: err}
	}
	return cfg, nil
}

// normalizeKeys lower-cases all keys of the mapping (recursively).
func normalizeKeys(m map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(m))
	for k, v := range m {
		out[strings.ToLower(k)] = normalizeValue(v)
	}
	return out
}

func normalizeValue(v interface{}) interface{} {
	switch x := v.(type) {
	case map[string]interface{}:
		return normalizeKeys(x)
	case map[interface{}]interface{}:
		m := make(map[string]interface{}, len(x))
		for k, val := range x {
			m[fmt.Sprintf("%v", k)] = val
		}
		return normalizeKeys(m)
	}
	return v
}

// ---------------------------------------------------------------------------
// Weakly typed decoding of the settings into the Config struct.

type fieldSpec struct {
	name       string // name as it appears in the config file (and in errors)
	hasDefault bool   // whether a default value is registered for the key
}

var fieldSpecs = []fieldSpec{
	{name: "ignoreSigs", hasDefault: true},
	{name: "extraIgnoreSigs"},
	{name: "ignoreSigRegexps"},
	{name: "ignorePackageGlobs"},
	{name: "ignoreInterfaceRegexps"},
	{name: "reportInternalErrors"},
}

// lookup returns the setting for the given field, and whether it is
// considered present.
func lookup(settings map[string]interface{}, spec fieldSpec) (interface{}, bool) {
	v, ok := settings[strings.ToLower(spec.name)]
	if !ok || v == nil {
		return nil, false
	}
	// An empty mapping has no leaf keys and therefore is invisible unless a
	// default exists for the key.
	if m, isMap := v.(map[string]interface{}); isMap && len(m) == 0 && !spec.hasDefault {
		return nil, false
	}
	return v, true
}

func decodeInto(settings map[string]interface{}, cfg *Config) error {
	var errs []string
	add := func(err error) {
		if err != nil {
			errs = append(errs, err.Error())
		}
	}

	for _, spec := range fieldSpecs {
		v, ok := lookup(settings, spec)
		if !ok {
			continue
		}
		switch spec.name {
		case "ignoreSigs":
			add(decodeStringSlice(spec.name, v, &cfg.IgnoreSigs))
		case "extraIgnoreSigs":
			add(decodeStringSlice(spec.name, v, &cfg.ExtraIgnoreSigs))
		case "ignoreSigRegexps":
			add(decodeStringSlice(spec.name, v, &cfg.IgnoreSigRegexps))
		case "ignorePackageGlobs":
			add(decodeStringSlice(spec.name, v, &cfg.IgnorePackageGlobs))
		case "ignoreInterfaceRegexps":
			add(decodeStringSlice(spec.name, v, &cfg.IgnoreInterfaceRegexps))
		case "reportInternalErrors":
			add(decodeBool(spec.name, v, &cfg.ReportInternalErrors))
		}
	}

	if len(errs) == 0 {
		return nil
	}
	points := make([]string, len(errs))
	for i, e := range errs {
		points[i] = "* " + e
	}
	sort.Strings(points)
	return fmt.Errorf("%d error(s) decoding:\n\n%s", len(errs), strings.Join(points, "\n"))
}

type multiError []string

func (m multiError) join() error {
	if len(m) == 0 {
		return nil
	}
	return errors.New(strings.Join(m, "\n"))
}

func typeName(v interface{}) string {
	return reflect.TypeOf(v).String()
}

func unconvertible(name, want string, v interface{}) error {
	return fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s', value: '%v'",
		name, want, typeName(v), v)
}

// decodeStringSlice converts v into a []string using relaxed rules:
// scalars are lifted into a one element slice, strings are split on commas
// and numbers/booleans are formatted as strings.
func decodeStringSlice(name string, v interface{}, out *[]string) error {
	if v == nil {
		return nil
	}
	switch x := v.(type) {
	case string:
		if x == "" {
			*out = []string{}
			return nil
		}
		*out = strings.Split(x, ",")
		return nil
	case []interface{}:
		res := make([]string, len(x))
		var errs multiError
		for i, elem := range x {
			if err := decodeString(fmt.Sprintf("%s[%d]", name, i), elem, &res[i]); err != nil {
				errs = append(errs, err.Error())
			}
		}
		*out = res
		return errs.join()
	case []string:
		*out = append([]string{}, x...)
		return nil
	case map[string]interface{}:
		if len(x) == 0 {
			*out = []string{}
			return nil
		}
		return decodeStringSlice(name, []interface{}{v}, out)
	default:
		return decodeStringSlice(name, []interface{}{v}, out)
	}
}

func decodeString(name string, v interface{}, out *string) error {
	if v == nil {
		return nil
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.String:
		*out = rv.String()
	case reflect.Bool:
		if rv.Bool() {
			*out = "1"
		} else {
			*out = "0"
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		*out = strconv.FormatInt(rv.Int(), 10)
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		*out = strconv.FormatUint(rv.Uint(), 10)
	case reflect.Float32, reflect.Float64:
		*out = strconv.FormatFloat(rv.Float(), 'f', -1, 64)
	case reflect.Slice, reflect.Array:
		if rv.Type().Elem().Kind() == reflect.Uint8 {
			*out = string(rv.Bytes())
			return nil
		}
		return unconvertible(name, "string", v)
	default:
		return unconvertible(name, "string", v)
	}
	return nil
}

func decodeBool(name string, v interface{}, out *bool) error {
	if v == nil {
		return nil
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Bool:
		*out = rv.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		*out = rv.Int() != 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		*out = rv.Uint() != 0
	case reflect.Float32, reflect.Float64:
		*out = rv.Float() != 0
	case reflect.String:
		b, err := strconv.ParseBool(rv.String())
		switch {
		case err == nil:
			*out = b
		case rv.String() == "":
			*out = false
		default:
			return fmt.Errorf("cannot parse '%s' as bool: %s", name, err)
		}
	default:
		return unconvertible(name, "bool", v)
	}
	return nil
}
EOF
