// Package analyzer implements the wrapcheck analysis: it reports errors
// that originate from other packages (or from interface methods) and are
// returned without being wrapped with additional context.
package analyzer

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"strings"

	"golang.org/x/tools/go/analysis"

	"errwrapcheck/internal/config"
	"errwrapcheck/internal/glob"
)

// Name is the analyzer name.
const Name = "wrapcheck"

// Doc is the analyzer documentation (first paragraph is the summary).
const Doc = "Checks that errors returned from external packages are wrapped"

// matcher is the interface satisfied by compiled glob patterns.
type matcher interface {
	Match(string) bool
}

// New returns an analyzer configured with cfg.
func New(cfg config.Config) *analysis.Analyzer {
	return &analysis.Analyzer{
		Name: Name,
		Doc:  Doc,
		Run: func(pass *analysis.Pass) (interface{}, error) {
			return run(pass, cfg)
		},
	}
}

// rules holds the compiled configuration used during a single pass.
type rules struct {
	cfg        config.Config
	ignoreSigs []string
	sigRes     []*regexp.Regexp
	ifaceRes   []*regexp.Regexp
	pkgGlobs   []matcher
}

func compileRegexps(patterns []string) ([]*regexp.Regexp, error) {
	out := make([]*regexp.Regexp, 0, len(patterns))
	for _, p := range patterns {
		re, err := regexp.Compile(p)
		if err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %v\n", p, err)
		}
		out = append(out, re)
	}
	return out, nil
}

func compileGlobs(patterns []string) ([]matcher, error) {
	out := make([]matcher, 0, len(patterns))
	for _, p := range patterns {
		var m matcher
		g, err := glob.Compile(p)
		if err != nil {
			// m is still nil here; the message reflects that.
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", m, err)
		}
		m = g
		out = append(out, m)
	}
	return out, nil
}

func newRules(cfg config.Config) (*rules, error) {
	r := &rules{cfg: cfg}
	r.ignoreSigs = append(append([]string{}, cfg.IgnoreSigs...), cfg.ExtraIgnoreSigs...)

	var err error
	if r.sigRes, err = compileRegexps(cfg.IgnoreSigRegexps); err != nil {
		return nil, err
	}
	if r.ifaceRes, err = compileRegexps(cfg.IgnoreInterfaceRegexps); err != nil {
		return nil, err
	}
	if r.pkgGlobs, err = compileGlobs(cfg.IgnorePackageGlobs); err != nil {
		return nil, err
	}
	return r, nil
}

func run(pass *analysis.Pass, cfg config.Config) (interface{}, error) {
	r, err := newRules(cfg)
	if err != nil {
		return nil, err
	}

	for _, file := range pass.Files {
		v := &visitor{pass: pass, file: file, rules: r}
		v.walk(file)
	}
	return nil, nil
}

// visitor walks a single file looking for return statements.
type visitor struct {
	pass  *analysis.Pass
	file  *ast.File
	rules *rules

	// stack of nodes currently being visited, used to determine whether
	// a return statement is nested inside a function literal.
	stack []ast.Node
}

func (v *visitor) inFuncLit() bool {
	for _, n := range v.stack {
		if _, ok := n.(*ast.FuncLit); ok {
			return true
		}
	}
	return false
}

func (v *visitor) walk(root ast.Node) {
	ast.Inspect(root, func(n ast.Node) bool {
		if n == nil {
			v.stack = v.stack[:len(v.stack)-1]
			return false
		}
		v.stack = append(v.stack, n)
		if ret, ok := n.(*ast.ReturnStmt); ok {
			v.checkReturn(ret)
		}
		return true
	})
}

// checkReturn inspects the values of a return statement.
func (v *visitor) checkReturn(ret *ast.ReturnStmt) {
	if len(ret.Results) == 0 {
		return
	}
	info := v.pass.TypesInfo

	for _, expr := range ret.Results {
		// A call expression returned directly: the callee is the source.
		if call, ok := expr.(*ast.CallExpr); ok {
			if !v.inFuncLit() {
				v.checkCall(call)
			}
			// Nothing after a call is inspected.
			return
		}

		if !isErrorType(info.TypeOf(expr)) {
			continue
		}

		ident, ok := expr.(*ast.Ident)
		if !ok {
			return
		}

		call := v.sourceCall(ident)
		if call == nil {
			return
		}
		v.report(call, ident.NamePos)
	}
}

// checkCall handles `return f(...)` where the call yields an error, either
// directly or as part of a tuple.
func (v *visitor) checkCall(call *ast.CallExpr) {
	t := v.pass.TypesInfo.TypeOf(call)
	if isErrorType(t) {
		v.report(call, call.Pos())
		return
	}
	tup, ok := t.(*types.Tuple)
	if !ok {
		return
	}
	for i := 0; i < tup.Len(); i++ {
		if isErrorType(tup.At(i).Type()) {
			v.report(call, call.Pos())
			return
		}
	}
}

// sourceCall determines the call expression whose result was most recently
// stored in the variable denoted by ident, or nil if it cannot be found.
func (v *visitor) sourceCall(ident *ast.Ident) *ast.CallExpr {
	obj := v.pass.TypesInfo.ObjectOf(ident)
	if obj == nil {
		return nil
	}

	if assign := v.latestAssignment(obj, ident.Pos()); assign != nil {
		if len(assign.Rhs) == 0 {
			return nil
		}
		call, _ := assign.Rhs[0].(*ast.CallExpr)
		return call
	}

	spec := v.declaration(obj)
	if spec == nil || len(spec.Values) == 0 {
		return nil
	}
	call, _ := spec.Values[0].(*ast.CallExpr)
	return call
}

// latestAssignment finds the assignment statement to obj that precedes
// pos and is closest to it, anywhere in the file.
func (v *visitor) latestAssignment(obj types.Object, pos token.Pos) *ast.AssignStmt {
	var best *ast.AssignStmt
	ast.Inspect(v.file, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if assign.Pos() >= pos {
			return true
		}
		for _, lhs := range assign.Lhs {
			id, ok := lhs.(*ast.Ident)
			if !ok {
				continue
			}
			if v.pass.TypesInfo.ObjectOf(id) == obj {
				if best == nil || assign.Pos() > best.Pos() {
					best = assign
				}
				break
			}
		}
		return true
	})
	return best
}

// declaration finds the var declaration of obj in the file.
func (v *visitor) declaration(obj types.Object) *ast.ValueSpec {
	var found *ast.ValueSpec
	ast.Inspect(v.file, func(n ast.Node) bool {
		if found != nil {
			return false
		}
		spec, ok := n.(*ast.ValueSpec)
		if !ok {
			return true
		}
		for _, name := range spec.Names {
			if v.pass.TypesInfo.ObjectOf(name) == obj {
				found = spec
				return false
			}
		}
		return true
	})
	return found
}

// report emits a diagnostic at pos for an unwrapped error produced by call,
// unless the call is exempted by the configuration.
func (v *visitor) report(call *ast.CallExpr, pos token.Pos) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return
	}
	info := v.pass.TypesInfo
	fn := info.ObjectOf(sel.Sel)
	if fn == nil {
		return
	}
	sig := types.ObjectString(fn, nil)

	for _, s := range v.rules.ignoreSigs {
		if strings.Contains(sig, s) {
			return
		}
	}
	for _, re := range v.rules.sigRes {
		if re.MatchString(sig) {
			return
		}
	}

	pkgPath := ""
	if fn.Pkg() != nil {
		pkgPath = fn.Pkg().Path()
	}
	pkgIgnored := v.packageIgnored(pkgPath)

	// Methods invoked through an interface value.
	if recv := info.TypeOf(sel.X); recv != nil {
		if _, isIface := recv.Underlying().(*types.Interface); isIface {
			name := types.TypeString(recv, func(p *types.Package) string { return p.Name() })
			if !v.interfaceIgnored(name) && !pkgIgnored {
				v.pass.Reportf(pos, "error returned from interface method should be wrapped: sig: %s", sig)
				return
			}
		}
	}

	external := fn.Pkg() != nil && pkgPath != v.pass.Pkg.Path() && !pkgIgnored
	if external {
		v.pass.Reportf(pos, "error returned from external package is unwrapped: sig: %s", sig)
		return
	}

	if v.rules.cfg.ReportInternalErrors {
		v.pass.Reportf(pos, "package-internal error should be wrapped: sig: %s", sig)
	}
}

func (v *visitor) packageIgnored(path string) bool {
	for _, g := range v.rules.pkgGlobs {
		if g.Match(path) {
			return true
		}
	}
	return false
}

func (v *visitor) interfaceIgnored(name string) bool {
	for _, re := range v.rules.ifaceRes {
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

var errorType = types.Universe.Lookup("error").Type()

// isErrorType reports whether t is exactly the predeclared error type.
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Identical(t, errorType)
}
