// Package driver implements the command line front end for a single
// analyzer: flag handling, package loading, running the analysis and
// printing the resulting diagnostics as text or JSON.
package driver

import (
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"go/token"
	"io"
	"log"
	"os"
	"runtime"
	"runtime/pprof"
	"runtime/trace"
	"sort"
	"strings"
	"time"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/checker"
	"golang.org/x/tools/go/analysis/unitchecker"
	"golang.org/x/tools/go/packages"
)

// Command line options.
var (
	jsonOutput   = false
	contextLines = -1
	applyFix     bool
	showDiff     bool

	debugFlags   = ""
	cpuProfile   string
	memProfile   string
	traceFile    string
	includeTests = true
)

func dbg(b byte) bool { return strings.IndexByte(debugFlags, b) >= 0 }

// Main runs the analyzer as a standalone command and exits the process.
func Main(a *analysis.Analyzer) {
	log.SetFlags(0)
	log.SetPrefix(a.Name + ": ")

	analyzers := []*analysis.Analyzer{a}

	if err := analysis.Validate(analyzers); err != nil {
		log.Fatal(err)
	}

	registerDriverFlags()

	flag.Usage = func() {
		paras := strings.Split(a.Doc, "\n\n")
		fmt.Fprintf(os.Stderr, "%s: %s\n\n", a.Name, paras[0])
		fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n", a.Name)
		if len(paras) > 1 {
			fmt.Fprintln(os.Stderr, strings.Join(paras[1:], "\n\n"))
		}
		fmt.Fprintln(os.Stderr, "\nFlags:")
		flag.PrintDefaults()
	}

	parseFlags(analyzers)

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	if len(args) == 1 && strings.HasSuffix(args[0], ".cfg") {
		unitchecker.Run(args[0], analyzers)
		panic("unreachable")
	}

	os.Exit(run(args, analyzers))
}

// registerDriverFlags registers the flags controlling the driver itself.
func registerDriverFlags() {
	flag.StringVar(&debugFlags, "debug", debugFlags, `debug flags, any subset of "fpstv"`)

	flag.StringVar(&cpuProfile, "cpuprofile", "", "write CPU profile to this file")
	flag.StringVar(&memProfile, "memprofile", "", "write memory profile to this file")
	flag.StringVar(&traceFile, "trace", "", "write trace log to this file")
	flag.BoolVar(&includeTests, "test", includeTests, "indicates whether test files should be analyzed, too")
}

// parseFlags registers the analyzer flags and the common flags, then
// parses the command line.
func parseFlags(analyzers []*analysis.Analyzer) {
	for _, a := range analyzers {
		a.Flags.VisitAll(func(f *flag.Flag) {
			if flag.Lookup(f.Name) != nil {
				log.Printf("%s flag -%s would conflict with driver; skipping", a.Name, f.Name)
				return
			}
			flag.Var(f.Value, f.Name, f.Usage)
		})
	}

	printflags := flag.Bool("flags", false, "print analyzer flags in JSON")
	if flag.Lookup("V") == nil {
		flag.Var(versionFlag{}, "V", "print version and exit")
	}

	flag.BoolVar(&jsonOutput, "json", jsonOutput, "emit JSON output")
	flag.IntVar(&contextLines, "c", contextLines, `display offending line with this many lines of context`)
	flag.BoolVar(&applyFix, "fix", false, "apply all suggested fixes")
	flag.BoolVar(&showDiff, "diff", false, "with -fix, don't update the files, but print a unified diff")

	// Legacy flags kept for compatibility with scripts written for vet.
	_ = flag.Bool("source", false, "no effect (deprecated)")
	_ = flag.Bool("v", false, "no effect (deprecated)")
	_ = flag.Bool("all", false, "no effect (deprecated)")
	_ = flag.String("tags", "", "no effect (deprecated)")

	flag.Parse()

	if *printflags {
		printFlags()
		os.Exit(0)
	}
}

func printFlags() {
	type jsonFlag struct {
		Name  string
		Bool  bool
		Usage string
	}
	var flags []jsonFlag
	flag.VisitAll(func(f *flag.Flag) {
		switch f.Name {
		case "debug", "cpuprofile", "memprofile", "trace", "fix":
			return
		}
		b, ok := f.Value.(interface{ IsBoolFlag() bool })
		isBool := ok && b.IsBoolFlag()
		flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
	})
	data, err := json.MarshalIndent(flags, "", "\t")
	if err != nil {
		log.Fatal(err)
	}
	os.Stdout.Write(data)
}

// versionFlag implements the -V flag understood by the go command.
type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() any         { return nil }
func (versionFlag) String() string   { return "" }
func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}
	progname, err := os.Executable()
	if err != nil {
		return err
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		log.Fatal(err)
	}
	f.Close()
	fmt.Printf("%s version devel comments-go-here buildID=%02x\n", progname, string(h.Sum(nil)))
	os.Exit(0)
	return nil
}

// run loads the packages named by args, analyzes them and prints the
// results. It returns the process exit code.
func run(args []string, analyzers []*analysis.Analyzer) (exitcode int) {
	exitAtLeast := func(code int) {
		if code > exitcode {
			exitcode = code
		}
	}

	if v := flag.CommandLine.Lookup("v"); v != nil &&
		v.Value.(flag.Getter).Get() == true &&
		!strings.Contains(debugFlags, "v") {
		debugFlags += "v"
	}

	if cpuProfile != "" {
		f, err := os.Create(cpuProfile)
		if err != nil {
			log.Fatal(err)
		}
		if err := pprof.StartCPUProfile(f); err != nil {
			log.Fatal(err)
		}
		defer pprof.StopCPUProfile()
	}

	if traceFile != "" {
		f, err := os.Create(traceFile)
		if err != nil {
			log.Fatal(err)
		}
		if err := trace.Start(f); err != nil {
			log.Fatal(err)
		}
		defer func() {
			trace.Stop()
			log.Printf("To view the trace, run:\n$ go tool trace view %s", traceFile)
		}()
	}

	if memProfile != "" {
		f, err := os.Create(memProfile)
		if err != nil {
			log.Fatal(err)
		}
		defer func() {
			runtime.GC()
			if err := pprof.WriteHeapProfile(f); err != nil {
				log.Fatalf("Writing memory profile: %v", err)
			}
			f.Close()
		}()
	}

	if dbg('v') {
		log.SetPrefix("")
		log.SetFlags(log.Lmicroseconds)
		log.Printf("load %s", args)
	}

	initial, err := load(args, needFacts(analyzers))
	if err != nil {
		log.Print(err)
		exitAtLeast(1)
		return
	}

	if n := packages.PrintErrors(initial); n > 0 {
		exitAtLeast(1)
	}

	var factLog io.Writer
	if dbg('f') {
		factLog = os.Stderr
	}

	opts := &checker.Options{
		SanityCheck: dbg('s'),
		Sequential:  dbg('p'),
		FactLog:     factLog,
	}
	if dbg('v') {
		log.Printf("building graph of analysis passes")
	}
	graph, err := checker.Analyze(analyzers, initial, opts)
	if err != nil {
		log.Print(err)
		exitAtLeast(1)
		return
	}

	if applyFix {
		// The analyzer offers no automatic fixes, so there is nothing to
		// apply; mirror the driver convention of not printing diagnostics.
		return
	}

	exitAtLeast(printDiagnostics(graph))
	return
}

// printDiagnostics prints the diagnostics and returns the exit code.
func printDiagnostics(graph *checker.Graph) (exitcode int) {
	if jsonOutput {
		if err := printJSON(os.Stdout, graph); err != nil {
			return 1
		}
	} else {
		if err := printText(os.Stderr, graph, contextLines); err != nil {
			return 1
		}

		var numErrors, rootDiags int
		for act := range graph.All() {
			if act.Err != nil {
				numErrors++
			} else if act.IsRoot {
				rootDiags += len(act.Diagnostics)
			}
		}
		if numErrors > 0 {
			exitcode = 1
		} else if rootDiags > 0 {
			exitcode = 3
		}
	}

	if dbg('t') {
		if !dbg('p') {
			log.Println("Warning: times are mostly GC/scheduler noise; use -debug=tp to disable parallelism")
		}
		var list []*checker.Action
		var total time.Duration
		for act := range graph.All() {
			list = append(list, act)
			total += act.Duration
		}
		sort.Slice(list, func(i, j int) bool {
			return list[i].Duration > list[j].Duration
		})
		var sum time.Duration
		for _, act := range list {
			fmt.Fprintf(os.Stderr, "%s\t%s\n", act.Duration, act)
			sum += act.Duration
			if sum >= total*9/10 {
				break
			}
		}
		if total > sum {
			fmt.Fprintf(os.Stderr, "%s\tall others\n", total-sum)
		}
	}

	return exitcode
}

// printText writes diagnostics in the classic "file:line:col: message"
// form, de-duplicating identical diagnostics (e.g. from test variants).
func printText(w io.Writer, graph *checker.Graph, contextLines int) error {
	type key struct {
		pos     token.Position
		end     token.Position
		a       *analysis.Analyzer
		message string
	}
	seen := make(map[key]bool)

	var buf strings.Builder
	for act := range graph.All() {
		if act.Err != nil {
			fmt.Fprintf(w, "%s: %v\n", act.Analyzer.Name, act.Err)
			continue
		}
		if !act.IsRoot {
			continue
		}
		for _, diag := range act.Diagnostics {
			posn := act.Package.Fset.Position(diag.Pos)
			end := act.Package.Fset.Position(diag.End)
			k := key{posn, end, act.Analyzer, diag.Message}
			if seen[k] {
				continue
			}
			seen[k] = true
			printPlain(&buf, act.Package.Fset, contextLines, diag)
		}
	}
	_, err := io.WriteString(w, buf.String())
	return err
}

func printPlain(out io.Writer, fset *token.FileSet, contextLines int, diag analysis.Diagnostic) {
	print := func(pos, end token.Pos, message string) {
		posn := fset.Position(pos)
		fmt.Fprintf(out, "%s: %s\n", posn, message)

		if contextLines >= 0 {
			endPosn := fset.Position(end)
			if !endPosn.IsValid() {
				endPosn = posn
			}
			data, _ := os.ReadFile(posn.Filename)
			lines := strings.Split(string(data), "\n")
			for i := posn.Line - contextLines; i <= endPosn.Line+contextLines; i++ {
				if 1 <= i && i <= len(lines) {
					fmt.Fprintf(out, "%d\t%s\n", i, lines[i-1])
				}
			}
		}
	}

	print(diag.Pos, diag.End, diag.Message)
	for _, rel := range diag.Related {
		print(rel.Pos, rel.End, "\t"+rel.Message)
	}
}

// JSON output types.
type jsonTextEdit struct {
	Filename string `json:"filename"`
	Start    int    `json:"start"`
	End      int    `json:"end"`
	New      string `json:"new"`
}

type jsonSuggestedFix struct {
	Message string         `json:"message"`
	Edits   []jsonTextEdit `json:"edits"`
}

type jsonDiagnostic struct {
	Category       string             `json:"category,omitempty"`
	Posn           string             `json:"posn"`
	Message        string             `json:"message"`
	SuggestedFixes []jsonSuggestedFix `json:"suggested_fixes,omitempty"`
}

type jsonError struct {
	Err string `json:"error"`
}

// printJSON writes a map from package ID to analyzer name to either a
// list of diagnostics or an error.
func printJSON(w io.Writer, graph *checker.Graph) error {
	tree := make(map[string]map[string]any)
	add := func(id, name string, v any) {
		m, ok := tree[id]
		if !ok {
			m = make(map[string]any)
			tree[id] = m
		}
		m[name] = v
	}

	for act := range graph.All() {
		fset := act.Package.Fset
		if act.Err != nil {
			add(act.Package.ID, act.Analyzer.Name, jsonError{act.Err.Error()})
			continue
		}
		if !act.IsRoot || len(act.Diagnostics) == 0 {
			continue
		}
		diags := make([]jsonDiagnostic, 0, len(act.Diagnostics))
		for _, d := range act.Diagnostics {
			var fixes []jsonSuggestedFix
			for _, fix := range d.SuggestedFixes {
				var edits []jsonTextEdit
				for _, edit := range fix.TextEdits {
					edits = append(edits, jsonTextEdit{
						Filename: fset.Position(edit.Pos).Filename,
						Start:    fset.Position(edit.Pos).Offset,
						End:      fset.Position(edit.End).Offset,
						New:      string(edit.NewText),
					})
				}
				fixes = append(fixes, jsonSuggestedFix{Message: fix.Message, Edits: edits})
			}
			diags = append(diags, jsonDiagnostic{
				Category:       d.Category,
				Posn:           fset.Position(d.Pos).String(),
				Message:        d.Message,
				SuggestedFixes: fixes,
			})
		}
		add(act.Package.ID, act.Analyzer.Name, diags)
	}

	data, err := json.MarshalIndent(tree, "", "\t")
	if err != nil {
		log.Panicf("internal error: JSON marshaling failed: %v", err)
	}
	_, err = fmt.Fprintf(w, "%s\n", data)
	return err
}

// load loads the packages matching the given patterns.
func load(patterns []string, allSyntax bool) ([]*packages.Package, error) {
	mode := packages.LoadSyntax
	if allSyntax {
		mode = packages.LoadAllSyntax
	}
	mode |= packages.NeedModule
	conf := packages.Config{
		Mode:  mode,
		Tests: includeTests,
	}
	initial, err := packages.Load(&conf, patterns...)
	if err == nil && len(initial) == 0 {
		err = fmt.Errorf("%s matched no packages", strings.Join(patterns, " "))
	}
	return initial, err
}

// needFacts reports whether any of the analyzers (transitively) uses facts,
// in which case the whole program must be loaded from source.
func needFacts(analyzers []*analysis.Analyzer) bool {
	seen := make(map[*analysis.Analyzer]bool)
	q := append([]*analysis.Analyzer{}, analyzers...)
	for len(q) > 0 {
		a := q[0]
		q = q[1:]
		if !seen[a] {
			seen[a] = true
			if len(a.FactTypes) > 0 {
				return true
			}
			q = append(q, a.Requires...)
		}
	}
	return false
}
