#!/usr/bin/env bash
# Builds ./executable from the sources in this repository.
set -euo pipefail
cd "$(dirname "$0")"

# ---------------------------------------------------------------------------
# Locate a Go toolchain recent enough for the dependencies (go >= 1.25).
# ---------------------------------------------------------------------------
version_ok() {
	local v
	v="$("$1" version 2>/dev/null | sed -n 's/^go version go\([0-9]*\)\.\([0-9]*\).*/\1 \2/p')" || return 1
	[ -n "$v" ] || return 1
	set -- $v
	[ "$1" -gt 1 ] || { [ "$1" -eq 1 ] && [ "$2" -ge 25 ]; }
}

GO=""
MODCACHE="${GOMODCACHE:-$(go env GOMODCACHE 2>/dev/null || true)}"
[ -n "$MODCACHE" ] || MODCACHE="/usr/local/go/mod-cache"

if command -v go >/dev/null 2>&1 && version_ok "$(command -v go)"; then
	GO="$(command -v go)"
else
	# Look for a toolchain that was downloaded into the module cache.
	for cand in "$MODCACHE"/golang.org/toolchain@v0.0.1-go1.2[5-9]*/bin/go \
	            "$MODCACHE"/golang.org/toolchain@v0.0.1-go1.[3-9][0-9]*/bin/go \
	            /usr/local/go*/bin/go /usr/lib/go*/bin/go "$HOME"/sdk/go*/bin/go; do
		if [ -x "$cand" ] && version_ok "$cand"; then
			GO="$cand"
			break
		fi
	done
fi

if [ -z "$GO" ]; then
	# Last resort: let the go command fetch the required toolchain.
	GO="$(command -v go)"
	export GOTOOLCHAIN=auto
else
	export GOTOOLCHAIN=local
