// the file, grouped by the variable they define or assign to.
func (v *visitor) index() {
	if v.assigns != nil {
		return
	}
	v.assigns = make(map[types.Object][]*ast.AssignStmt)
	v.decls = make(map[types.Object]*ast.ValueSpec)
	info := v.pass.TypesInfo

	ast.Inspect(v.file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			seen := make(map[types.Object]bool)
			for _, lhs := range n.Lhs {
				id, ok := lhs.(*ast.Ident)
				if !ok {
