package basic

import (
	"errors"
	"fmt"

	"basic/ext"
)

func internal() error { return errors.New("internal") }

func direct() error {
	return ext.Fail() // want `error returned from external package is unwrapped: sig: func basic/ext.Fail\(\) error`
}

func tuple() (int, error) {
	return ext.Pair() // want `error returned from external package is unwrapped: sig: func basic/ext.Pair\(\) \(int, error\)`
}

func viaVariable() error {
	_, err := ext.Pair()
	if err != nil {
		return err // want `error returned from external package is unwrapped: sig: func basic/ext.Pair\(\) \(int, error\)`
	}
	return nil
}

func wrapped() error {
	if err := ext.Fail(); err != nil {
		return fmt.Errorf("wrapped: %w", err)
	}
	return nil
}

func fromInterface(r ext.Runner) error {
	return r.Run() // want `error returned from interface method should be wrapped: sig: func \(basic/ext.Runner\).Run\(\) error`
}

func fromInternal() error {
	err := internal()
	return err
}

func method(t *ext.Thing) error {
	return t.Close() // want `error returned from external package is unwrapped: sig: func \(\*basic/ext.Thing\).Close\(\) error`
}

func reassigned() error {
	err := ext.Fail()
	err = internal()
	return err
}

func inClosure() error {
	f := func() error {
		return ext.Fail() // calls inside function literals are not reported
	}
	return f()
}

func identInClosure() error {
	err := ext.Fail()
	f := func() error {
		return err // want `error returned from external package is unwrapped: sig: func basic/ext.Fail\(\) error`
	}
	return f()
}
EOF
