package config

import (
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// chdir changes into a fresh temporary directory (with an empty HOME) for
// the duration of the test.
func chdir(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	home := t.TempDir()
	old, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	t.Setenv("HOME", home)
	t.Cleanup(func() { os.Chdir(old) })
	return dir
}

func TestNoFile(t *testing.T) {
	chdir(t)
	cfg, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(cfg.IgnoreSigs, DefaultIgnoreSigs) {
		t.Errorf("got %v, want defaults", cfg.IgnoreSigs)
	}
}

func TestOverrides(t *testing.T) {
	dir := chdir(t)
	content := `
ignoreSigs: [".Wrap("]
extraIgnoreSigs: ".Custom(,.Other("
ignorePackageGlobs: ["encoding/*"]
REPORTINTERNALERRORS: 1
`
	if err := os.WriteFile(filepath.Join(dir, ".wrapcheck.yaml"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	cfg, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if want := []string{".Wrap("}; !reflect.DeepEqual(cfg.IgnoreSigs, want) {
		t.Errorf("IgnoreSigs = %v, want %v", cfg.IgnoreSigs, want)
	}
	if want := []string{".Custom(", ".Other("}; !reflect.DeepEqual(cfg.ExtraIgnoreSigs, want) {
		t.Errorf("ExtraIgnoreSigs = %v, want %v", cfg.ExtraIgnoreSigs, want)
	}
	if !cfg.ReportInternalErrors {
		t.Errorf("ReportInternalErrors = false, want true")
	}
}

func TestDecodeErrors(t *testing.T) {
	dir := chdir(t)
	content := "reportInternalErrors: maybe\nignoreSigs: [[a]]\n"
	if err := os.WriteFile(filepath.Join(dir, ".wrapcheck.yml"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := Load()
	if err == nil {
		t.Fatal("expected error")
	}
	if _, ok := err.(*DecodeError); !ok {
		t.Fatalf("expected *DecodeError, got %T", err)
	}
	want := "2 error(s) decoding:\n\n" +
		"* 'ignoreSigs[0]' expected type 'string', got unconvertible type '[]interface {}', value: '[a]'\n" +
		"* cannot parse 'reportInternalErrors' as bool: strconv.ParseBool: parsing \"maybe\": invalid syntax"
	if err.Error() != want {
		t.Errorf("got error:\n%s\nwant:\n%s", err.Error(), want)
	}
}

func TestParseError(t *testing.T) {
	dir := chdir(t)
	if err := os.WriteFile(filepath.Join(dir, ".wrapcheck.yaml"), []byte("ignoreSigs: [\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := Load()
	if err == nil {
		t.Fatal("expected error")
	}
	if _, ok := err.(*ParseError); !ok {
		t.Fatalf("expected *ParseError, got %T", err)
	}
	if !strings.HasPrefix(err.Error(), "While parsing config: yaml:") {
		t.Errorf("unexpected message %q", err.Error())
	}
}
EOF
